#!/usr/bin/env python3
from __future__ import annotations
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
FR_HUBS=["restaurants/index.html","plages/index.html","escapades/index.html","culture/index.html","hotels/sans-voiture/index.html"]
EN_HUBS=["en/restaurants/index.html","en/beaches/index.html","en/day-trips/index.html","en/culture/index.html","en/hotels/without-a-car/index.html"]
TOUCHED=FR_HUBS+EN_HUBS+["riviera-guide/nice/index.html","en/riviera-guide/nice/index.html","riviera-guide/monaco/index.html","en/riviera-guide/monaco/index.html","riviera-guide/cannes/index.html","en/riviera-guide/cannes/index.html","riviera-guide/eze/index.html","plan/five-days-nice-no-car/index.html","fr/planifier/cinq-jours-nice-sans-voiture/index.html","restaurants/nice/index.html","en/restaurants/nice/index.html"]

def rd(p):
    q=ROOT/p
    if not q.is_file(): raise FileNotFoundError(p)
    return q.read_text(encoding="utf-8")
def wr(p,s):
    q=ROOT/p;q.parent.mkdir(parents=True,exist_ok=True);q.write_text(s,encoding="utf-8")
def nav(s,lang):
    if lang=="fr":
        return re.sub(r'<a(?P<a>[^>]*?)href="/restaurants/"(?P<b>[^>]*)>(?:Manger\s*&amp;\s*faire|Manger\s*&\s*faire|Explorer)</a>',lambda m:f'<a{m.group("a")}href="/explore/"{m.group("b")}>Explorer</a>',s)
    return re.sub(r'<a(?P<a>[^>]*?)href="/en/restaurants/"(?P<b>[^>]*)>(?:Eat\s*&amp;\s*Do|Eat\s*&\s*Do|Explore)</a>',lambda m:f'<a{m.group("a")}href="/en/explore/"{m.group("b")}>Explore</a>',s)
def footer(lang):
    if lang=="fr": return '<footer class="site-footer"><nav aria-label="Plan du site" class="site-footer-nav"><a href="/fr/#planifier">Planifier</a><a href="/explore/">Explorer</a><a href="/riviera-guide/">Lieux</a><a href="/fr/dormir/nice/">Dormir</a><a href="/bons-plans/">Maintenant</a><a href="/a-propos/">À propos</a></nav><div>Sélection éditoriale indépendante. Vérifiée en septembre 2026. Les horaires, cartes et prix peuvent changer : vérifiez avant de réserver.</div><div style="margin-top:10px">© 2026 Mametas · They know the Riviera.</div><div class="privacy-links"><a href="/fr/confidentialite/" data-privacy-link="true">Confidentialité &amp; cookies</a> · <a href="/en/">English</a></div></footer>'
    return '<footer class="site-footer"><nav aria-label="Site map" class="site-footer-nav"><a href="/#plan">Plan</a><a href="/en/explore/">Explore</a><a href="/en/riviera-guide/">Places</a><a href="/stay/nice/">Stay</a><a href="/en/good-finds/">Now</a><a href="/en/about/">About</a></nav><div>Independent editorial selection. Checked September 2026. Opening hours, menus and prices can change: verify before booking.</div><div style="margin-top:10px">© 2026 Mametas · They know the Riviera.</div><div class="privacy-links"><a href="/en/privacy/" data-privacy-link="true">Privacy &amp; cookies</a> · <a href="/fr/">Français</a></div></footer>'
def foot(s,lang): return re.sub(r'<footer\b.*?</footer>',footer(lang),s,count=1,flags=re.S) if '<footer' in s else s.replace('</body>',footer(lang)+'</body>')
def mobile(s,lang):
    if 'data-mobile-nav' in s or 'data-v3-menu' in s or 'class="primary-nav"' not in s:return s
    if lang=="fr": menu='<div class="mobile-nav" data-mobile-nav=""><div class="mobile-nav-top"><span class="brand-name">Mametas</span><button aria-label="Fermer" class="mobile-nav-close" data-menu-close="">×</button></div><ul><li><a href="/fr/#planifier">Planifier</a></li><li><a href="/riviera-guide/">Lieux</a></li><li><a href="/fr/dormir/nice/">Dormir</a></li><li><a href="/explore/">Explorer</a></li><li><a href="/bons-plans/">Maintenant</a></li></ul></div>'
    else: menu='<div class="mobile-nav" data-mobile-nav=""><div class="mobile-nav-top"><span class="brand-name">Mametas</span><button aria-label="Close" class="mobile-nav-close" data-menu-close="">×</button></div><ul><li><a href="/#plan">Plan</a></li><li><a href="/en/riviera-guide/">Places</a></li><li><a href="/stay/nice/">Stay</a></li><li><a href="/en/explore/">Explore</a></li><li><a href="/en/good-finds/">Now</a></li></ul></div>'
    return s.replace('</div></header>','<button aria-label="Menu" class="menu-toggle" data-menu-open=""><span></span><span></span><span></span></button></div></header>'+menu,1)
def before_end(s,h):
    p=s.rfind('</article>');p=p if p>=0 else s.rfind('</main>')
    if p<0: raise RuntimeError('No article/main closing tag')
    return s[:p]+h+s[p:]

def patch_hubs():
    for p in FR_HUBS: wr(p,foot(mobile(nav(rd(p),'fr'),'fr'),'fr'))
    for p in EN_HUBS: wr(p,foot(mobile(nav(rd(p),'en'),'en'),'en'))

def counters():
    slugs=['nice','villefranche-sur-mer','antibes','cannes','monaco','menton','saint-tropez','saint-paul-de-vence','mougins','theoule-sur-mer','grasse'];counts={}
    for x in slugs:
        a=len(re.findall(r'class="place"',rd(f'restaurants/{x}/index.html')));b=len(re.findall(r'class="place"',rd(f'en/restaurants/{x}/index.html')))
        if a!=b: raise RuntimeError(f'restaurant parity {x}: FR={a}, EN={b}')
        counts[x]=a
    if counts['cannes']!=10: raise RuntimeError(f'Cannes must have 10 restaurants, got {counts["cannes"]}')
    total=sum(counts.values())
    for p,lang,prefix in [('restaurants/index.html','fr','/restaurants/'),('en/restaurants/index.html','en','/en/restaurants/')]:
        s=rd(p)
        for x,n in counts.items():
            lab='ADRESSES' if lang=='fr' else 'ADDRESSES';pat=rf'(href="{re.escape(prefix+x+"/")}".*?<span class="kicker">)\d+\s+(?:ADRESSES|ADDRESSES)(</span>)'
            s,k=re.subn(pat,rf'\g<1>{n} {lab}\2',s,count=1,flags=re.S)
            if k!=1: raise RuntimeError(f'counter {x} not found in {p}')
        if lang=='fr':
            s=re.sub(r'<title>Restaurants sur la Côte d’Azur : \d+ adresses',f'<title>Restaurants sur la Côte d’Azur : {total} adresses',s,1);s=re.sub(r'<meta content="[^"]*restaurants sur la Riviera :',f'<meta content="{total} restaurants sur la Riviera :',s,1);s=re.sub(r'<p class="lead">[^<]*adresses\.',f'<p class="lead">{total} adresses.',s,1)
        else:
            s=re.sub(r'<title>French Riviera restaurants: \d+ addresses',f'<title>French Riviera restaurants: {total} addresses',s,1);s=re.sub(r'<meta content="[^"]*restaurants across the Riviera:',f'<meta content="{total} restaurants across the Riviera:',s,1);s=re.sub(r'<p class="lead">[^<]*addresses\.',f'<p class="lead">{total} addresses.',s,1)
        wr(p,s)

def nice_visual(p,alt):
    s=rd(p);s,n=re.subn(r'<figure class="culture-hero-media"><img[^>]+(?:commons\.wikimedia\.org|upload\.wikimedia\.org)[^>]*>.*?</figure>',f'<figure class="culture-hero-media"><img alt="{alt}" loading="eager" src="/assets/editorial/nice-riviera.jpg"/></figure>',s,1,flags=re.S)
    if n==0 and '/assets/editorial/nice-riviera.jpg' not in s: raise RuntimeError(f'Nice visual not patched: {p}')
    wr(p,s)

def nice_guides():
    p='riviera-guide/nice/index.html';s=rd(p)
    if '/bons-plans/nice-quand-il-pleut/' not in s:s=before_end(s,'<div class="culture-practical"><span>SI LE PROGRAMME DÉRAILLE</span><p><strong>Pluie :</strong> ne forcez pas la promenade comme si le ciel avait signé votre planning. <a href="/bons-plans/nice-quand-il-pleut/">Voici notre plan Nice quand il pleut →</a> <strong>Et avant de surcharger les journées :</strong> <a href="/bons-plans/erreurs-riviera/">7 façons de rater la Riviera →</a></p></div><div class="culture-practical"><span>FORTE CHALEUR</span><p>En période très chaude, gardez les montées et longues marches pour le matin, utilisez musées, déjeuner long ou baignade au cœur de la journée, puis reprenez dehors plus tard. Une journée raccourcie vaut mieux qu’un itinéraire « optimisé » à 14 h sur du bitume.</p></div>')
    wr(p,nav(s,'fr'))
    p='en/riviera-guide/nice/index.html';s=rd(p)
    if '/en/good-finds/nice-in-the-rain/' not in s:s=before_end(s,'<div class="culture-practical"><span>WHEN THE PLAN BREAKS</span><p><strong>Rain:</strong> do not force the promenade because a spreadsheet expected blue sky. <a href="/en/good-finds/nice-in-the-rain/">Use our Nice-in-the-rain plan →</a> <strong>Before you overload the week:</strong> <a href="/en/good-finds/riviera-mistakes/">7 ways to get the Riviera wrong →</a></p></div><div class="culture-practical"><span>VERY HOT DAYS</span><p>When the heat is intense, put climbs and long walks in the morning, use museums, a long lunch or a swim through the middle of the day, then go outside again later. A shorter day is better than an “efficient” itinerary on hot pavement at 2pm.</p></div>')
    wr(p,nav(s,'en'))

def monaco():
    for p,lang in [('riviera-guide/monaco/index.html','fr'),('en/riviera-guide/monaco/index.html','en')]:
        s=rd(p);mark='FORTE CHALEUR' if lang=='fr' else 'VERY HOT DAYS'
        if mark not in s:
            h='<div class="culture-practical"><span>FORTE CHALEUR</span><p>Monaco additionne pentes, escaliers et surfaces minérales. Les jours très chauds, faites le Rocher ou les jardins tôt, gardez les intérieurs et le déjeuner pour le milieu de journée, et évitez de transformer les dénivelés en épreuve d’endurance.</p></div>' if lang=='fr' else '<div class="culture-practical"><span>VERY HOT DAYS</span><p>Monaco combines slopes, stairs and a lot of stone. On very hot days, do the Rock or gardens early, keep indoor stops and lunch for the middle of the day, and do not turn the elevation into an endurance event.</p></div>'
            s=before_end(s,h)
        wr(p,nav(s,lang))

def without_car():
    p='hotels/sans-voiture/index.html';s=rd(p)
    repl={'<h2>Nice centre</h2><p>':'<h2>Nice centre</h2><p><a class="place-link" href="/fr/dormir/nice/#pratique">Voir la sélection la plus pratique à Nice →</a></p><p>','<h2>Vieux-Nice</h2><p>':'<h2>Vieux-Nice</h2><p><a class="place-link" href="/fr/dormir/nice/#anime">Voir les hôtels pour vivre le Vieux-Nice à pied →</a></p><p>','<h2>Le Port</h2><p>':'<h2>Le Port</h2><p><a class="place-link" href="/hotels/la-perouse/">Voir La Pérouse, entre vieille ville, mer et Port →</a></p><p>','<h2>Villefranche-sur-Mer</h2><p>':'<h2>Villefranche-sur-Mer</h2><p><a class="place-link" href="/hotels/villefranche-sur-mer/">Voir la courte sélection à Villefranche →</a></p><p>','<h2>Cannes centre</h2><p>':'<h2>Cannes centre</h2><p><a class="place-link" href="/hotels/cannes/">Voir les hôtels de Cannes selon le type de séjour →</a></p><p>'}
    for a,b in repl.items():
        if a in s and b not in s:s=s.replace(a,b,1)
    wr(p,nav(s,'fr'))
    p='en/hotels/without-a-car/index.html';s=rd(p)
    repl={'<h2>Central Nice</h2><p>':'<h2>Central Nice</h2><p><a class="place-link" href="/stay/nice/#practical">See the practical Nice shortlist →</a></p><p>','<h2>Old Nice</h2><p>':'<h2>Old Nice</h2><p><a class="place-link" href="/stay/nice/#active">See the lively Nice shortlist →</a></p><p>','<h2>The Port</h2><p>':'<h2>The Port</h2><p><a class="place-link" href="/en/hotels/nice/">Compare the Nice hotel shortlist →</a></p><p>','<h2>Villefranche-sur-Mer</h2><p>':'<h2>Villefranche-sur-Mer</h2><p><a class="place-link" href="/en/hotels/villefranche-sur-mer/">See the short Villefranche hotel selection →</a></p><p>','<h2>Central Cannes</h2><p>':'<h2>Central Cannes</h2><p><a class="place-link" href="/en/hotels/cannes/">See Cannes hotels by trip style →</a></p><p>'}
    for a,b in repl.items():
        if a in s and b not in s:s=s.replace(a,b,1)
    wr(p,nav(s,'en'))

def cannes():
    for p,lang in [('riviera-guide/cannes/index.html','fr'),('en/riviera-guide/cannes/index.html','en')]:
        s=nav(rd(p),lang);s=re.sub(r'<a class="culture-card" href="https://www\.cannes-france\.com/[^\"]*le-suquet[^\"]*" rel="nofollow noopener" target="_blank">','<a class="culture-card" href="#suquet">',s,1);s=re.sub(r'<a class="culture-card" href="https://www\.cannes-france\.com/[^\"]*marche-forville[^\"]*" rel="nofollow noopener" target="_blank">','<a class="culture-card" href="#forville">',s,1)
        if 'id="suquet"' not in s:
            mini='<div class="culture-practical" id="suquet"><span>LE SUQUET · COMMENT LE FAIRE</span><p>Montez pour les ruelles, le relief et la vue, puis redescendez vers le Vieux Port. Une heure à une heure trente suffit si vous ne faites pas le musée ; ajoutez le <a href="/culture/musee-explorations-cannes/">Musée des Explorations du Monde</a> si vous voulez donner plus de poids culturel à la visite.</p></div><div class="culture-practical" id="forville"><span>FORVILLE · LE BON MOMENT</span><p>Faites-en un mouvement du matin, puis enchaînez avec le Suquet ou le déjeuner. Pour manger autour, utilisez directement notre <a href="/restaurants/cannes/">courte sélection de tables à Cannes</a> plutôt que de ressortir du site vers une liste générique.</p></div>' if lang=='fr' else '<div class="culture-practical" id="suquet"><span>LE SUQUET · HOW TO USE IT</span><p>Go up for the lanes, the elevation and the view, then come back down toward the Old Port. An hour to ninety minutes is enough without the museum; add the <a href="/en/culture/musee-explorations-cannes/">Musée des Explorations du Monde</a> if you want a stronger cultural stop.</p></div><div class="culture-practical" id="forville"><span>FORVILLE · THE RIGHT MOMENT</span><p>Make it a morning move, then continue to Le Suquet or lunch. For food around the market, use our <a href="/en/restaurants/cannes/">short Cannes restaurant selection</a> rather than leaving Mametas for another generic list.</p></div>'
            a=s.find('</section>');b=s.find('<section',a+10)
            if b<0:raise RuntimeError(f'Cannes section placement failed: {p}')
            s=s[:b]+'<section class="section"><div class="wrap">'+mini+'</div></section>'+s[b:]
        wr(p,s)

def eze(lang):
    if lang=='fr': return '''<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8"/><meta content="width=device-width,initial-scale=1" name="viewport"/><title>Èze : quand y aller, comment monter et quoi éviter | Mametas</title><meta content="Le guide Mametas d’Èze : accès depuis Nice, meilleur moment, priorités, pièges, réservations et comment l’intégrer à un séjour sans voiture." name="description"/><link href="https://www.mametas.com/riviera-guide/eze/" rel="canonical"/><link href="https://www.mametas.com/riviera-guide/eze/" hreflang="fr" rel="alternate"/><link href="https://www.mametas.com/en/riviera-guide/eze/" hreflang="en" rel="alternate"/><link href="https://www.mametas.com/en/riviera-guide/eze/" hreflang="x-default" rel="alternate"/><link href="/assets/site.css?v=23.0" rel="stylesheet"/><meta content="index,follow,max-image-preview:large" name="robots"/><link href="/favicon.svg" rel="icon" type="image/svg+xml"/><script defer src="/assets/consent.js?v=1.0"></script></head><body><header class="site-header"><div class="header-inner"><a class="brand" href="/fr/"><span class="brand-name">Mametas</span><span class="brand-sub">They know the Riviera.</span></a><nav class="primary-nav"><ul><li><a href="/fr/#planifier">Planifier</a></li><li><a aria-current="page" href="/riviera-guide/">Lieux</a></li><li><a href="/fr/dormir/nice/">Dormir</a></li><li><a href="/explore/">Explorer</a></li><li><a href="/bons-plans/">Maintenant</a></li></ul></nav><div class="lang-switch"><a class="active" href="/riviera-guide/eze/">FR</a><span>|</span><a href="/en/riviera-guide/eze/">EN</a></div><button aria-label="Menu" class="menu-toggle" data-menu-open=""><span></span><span></span><span></span></button></div></header><div class="mobile-nav" data-mobile-nav=""><div class="mobile-nav-top"><span class="brand-name">Mametas</span><button aria-label="Fermer" class="mobile-nav-close" data-menu-close="">×</button></div><ul><li><a href="/fr/#planifier">Planifier</a></li><li><a href="/riviera-guide/">Lieux</a></li><li><a href="/fr/dormir/nice/">Dormir</a></li><li><a href="/explore/">Explorer</a></li><li><a href="/bons-plans/">Maintenant</a></li></ul></div><main><article class="article"><a class="back" href="/riviera-guide/">← Toutes les destinations</a><div class="meta">RIVIERA GUIDE • ÈZE</div><h1>Èze</h1><p class="standfirst">Le village est réellement spectaculaire. Le piège consiste à croire que « spectaculaire » signifie « à n’importe quelle heure, par n’importe quel moyen et avec Monaco coincé dans la même demi-journée ».</p><div class="verdict"><span class="label">LE VERDICT MAMETAS</span><p>Depuis Nice, Èze fonctionne très bien comme demi-journée choisie. Arrivez tôt, montez directement au village, gardez du temps pour le Jardin Exotique et repartez avant de transformer la vue en file d’attente.</p></div><h2>Depuis Nice : visez le village, pas la gare</h2><p>La gare d’Èze-sur-Mer se trouve sur la côte, très en dessous du village perché. Pour une visite classique, utilisez un bus qui monte au village ou un taxi/VTC ; vérifiez l’itinéraire du jour dans le calculateur officiel avant de partir. Le train n’est pas un raccourci magique jusqu’aux ruelles.</p><h2>Le bon timing</h2><p><strong>Deux à quatre heures</strong> suffisent pour les ruelles, les points de vue et le Jardin Exotique si vous ne transformez pas chaque boutique en étape. Arrivez le matin. En haute saison, le milieu de journée cumule chaleur et groupes ; vous pouvez faire mieux.</p><h2>À prioriser</h2><p class="mini-rule"><strong>Le village lui-même.</strong> Passages, pierre, vues et changements de niveau sont l’expérience.</p><p class="mini-rule"><strong>Le Jardin Exotique.</strong> C’est le point de vue qui justifie vraiment la montée pour beaucoup de visiteurs ; vérifiez horaires et conditions d’accès le jour même.</p><p class="mini-rule"><strong>Un déjeuner choisi, si le repas compte.</strong> Pour une table-destination ou <a href="/hotels/la-chevre-d-or/">La Chèvre d’Or</a>, réservez.</p><h2>À éviter</h2><p class="mini-rule"><strong>Gare côtière + montée improvisée.</strong> Le sentier de Nietzsche est une vraie marche raide, pas un transfert pittoresque avec valise ou sandales.</p><p class="mini-rule"><strong>Èze + Monaco en mode chronomètre.</strong> C’est faisable ; ce n’est pas automatiquement agréable. Si vous n’avez que cinq jours, gardez Èze comme journée flexible.</p><p class="mini-rule"><strong>Le cœur de journée par forte chaleur.</strong> Pierre, pente et peu d’ombre : commencez tôt ou décalez.</p><h2>Faut-il réserver ?</h2><p>Pas pour entrer dans le village. Oui pour une table importante, un hôtel ou une expérience guidée précise. Pour le reste, choisissez surtout votre heure et gardez une porte de sortie si la météo ou la foule change le calcul.</p><div class="source-box"><strong>Pour le transport :</strong> vérifiez le trajet du jour sur <a href="https://www.lignesdazur.com/" rel="nofollow noopener" target="_blank">Lignes d’Azur</a>. Les lignes et horaires peuvent changer.</div><div class="culture-practical"><span>PROCHAINE DÉCISION</span><p>Èze apparaît au jour 5 de notre <a href="/fr/planifier/cinq-jours-nice-sans-voiture/">plan de cinq jours sans voiture</a>. Si vous voulez dormir sur place, commencez par <a href="/hotels/eze/">la sélection d’hôtels à Èze</a>.</p></div></article></main>'''+footer('fr')+'''<script src="/assets/site.js"></script></body></html>'''
    return '''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"/><meta content="width=device-width,initial-scale=1" name="viewport"/><title>Èze: when to go, how to get up and what to avoid | Mametas</title><meta content="The Mametas guide to Èze: access from Nice, timing, priorities, traps, bookings and how to fit the village into a car-free Riviera trip." name="description"/><link href="https://www.mametas.com/en/riviera-guide/eze/" rel="canonical"/><link href="https://www.mametas.com/riviera-guide/eze/" hreflang="fr" rel="alternate"/><link href="https://www.mametas.com/en/riviera-guide/eze/" hreflang="en" rel="alternate"/><link href="https://www.mametas.com/en/riviera-guide/eze/" hreflang="x-default" rel="alternate"/><link href="/assets/site.css?v=23.0" rel="stylesheet"/><meta content="index,follow,max-image-preview:large" name="robots"/><link href="/favicon.svg" rel="icon" type="image/svg+xml"/><script defer src="/assets/consent.js?v=1.0"></script></head><body><header class="site-header"><div class="header-inner"><a class="brand" href="/"><span class="brand-name">Mametas</span><span class="brand-sub">They know the Riviera.</span></a><nav class="primary-nav"><ul><li><a href="/#plan">Plan</a></li><li><a aria-current="page" href="/en/riviera-guide/">Places</a></li><li><a href="/stay/nice/">Stay</a></li><li><a href="/en/explore/">Explore</a></li><li><a href="/en/good-finds/">Now</a></li></ul></nav><div class="lang-switch"><a href="/riviera-guide/eze/">FR</a><span>|</span><a class="active" href="/en/riviera-guide/eze/">EN</a></div><button aria-label="Menu" class="menu-toggle" data-menu-open=""><span></span><span></span><span></span></button></div></header><div class="mobile-nav" data-mobile-nav=""><div class="mobile-nav-top"><span class="brand-name">Mametas</span><button aria-label="Close" class="mobile-nav-close" data-menu-close="">×</button></div><ul><li><a href="/#plan">Plan</a></li><li><a href="/en/riviera-guide/">Places</a></li><li><a href="/stay/nice/">Stay</a></li><li><a href="/en/explore/">Explore</a></li><li><a href="/en/good-finds/">Now</a></li></ul></div><main><article class="article"><a class="back" href="/en/riviera-guide/">← All destinations</a><div class="meta">RIVIERA GUIDE • ÈZE</div><h1>Èze</h1><p class="standfirst">The village really is spectacular. The trap is assuming that “spectacular” means “at any hour, by any route, with Monaco squeezed into the same half-day”.</p><div class="verdict"><span class="label">THE MAMETAS VERDICT</span><p>From Nice, Èze works very well as a chosen half-day. Arrive early, go straight to the hilltop village, leave time for the Exotic Garden and move on before the view turns into a queue.</p></div><h2>From Nice: aim for the village, not the station</h2><p>Èze-sur-Mer station is on the coast, far below the hilltop village. For a standard visit, use a bus that climbs to the village or a taxi/ride-hail; check the day’s route in the official planner before leaving. The train is not a magic shortcut to the lanes.</p><h2>The right timing</h2><p><strong>Two to four hours</strong> is enough for the lanes, viewpoints and Exotic Garden. Go in the morning. In peak season, midday combines heat and groups; you can do better.</p><h2>Prioritise</h2><p class="mini-rule"><strong>The village itself.</strong> Passages, stone, views and level changes are the experience.</p><p class="mini-rule"><strong>The Exotic Garden.</strong> For many visitors this is the viewpoint that justifies the climb; check opening hours and access conditions on the day.</p><p class="mini-rule"><strong>A chosen lunch, if the meal matters.</strong> For a destination table or hotel, reserve; use the <a href="/en/hotels/eze/">short Èze hotel selection</a> if staying overnight.</p><h2>Avoid</h2><p class="mini-rule"><strong>Coastal station + improvised climb.</strong> The Nietzsche path is a real steep walk, not a picturesque transfer with luggage or sandals.</p><p class="mini-rule"><strong>Èze + Monaco on a stopwatch.</strong> It is possible; it is not automatically pleasant. On a five-day first trip, keep Èze as the flexible day.</p><p class="mini-rule"><strong>Midday in serious heat.</strong> Stone, slope and limited shade: start early or shift the visit.</p><h2>Do you need to book?</h2><p>Not to enter the village. Yes for an important restaurant, hotel or a specific guided experience. Otherwise, choose your timing and keep an exit if weather or crowds change the calculation.</p><div class="source-box"><strong>For transport:</strong> check the day’s journey on <a href="https://www.lignesdazur.com/en" rel="nofollow noopener" target="_blank">Lignes d’Azur</a>. Routes and timetables can change.</div><div class="culture-practical"><span>NEXT DECISION</span><p>Èze is day 5 in our <a href="/plan/five-days-nice-no-car/">five-day car-free plan</a>. If you want to stay rather than visit, start with the <a href="/en/hotels/eze/">short Èze hotel selection</a>.</p></div></article></main>'''+footer('en')+'''<script src="/assets/site.js"></script></body></html>'''
def patch_eze():wr('riviera-guide/eze/index.html',eze('fr'));wr('en/riviera-guide/eze/index.html',eze('en'))

def plan():
    p='plan/five-days-nice-no-car/index.html';s=nav(rd(p),'en')
    if '/en/riviera-guide/eze/' not in s:s=s.replace('<p><strong>Mametas rule:</strong> the flexible day is not a failure of planning. It is the part that makes the rest feel like a holiday.</p></div>','<p><strong>Mametas rule:</strong> the flexible day is not a failure of planning. It is the part that makes the rest feel like a holiday.</p><p><a class="inline-decision-link" href="/en/riviera-guide/eze/">If you choose Èze, use the village plan rather than improvising the climb →</a></p></div>',1)
    if 'Bad weather is not a cancelled trip' not in s:s=s.replace('<h2 id="book-ahead">','<div class="verdict-box"><span>Bad weather is not a cancelled trip</span><p>If Nice wakes up grey, switch rather than sulk: <a href="/en/good-finds/nice-in-the-rain/">use the Nice-in-the-rain plan</a>. Before adding another day trip, read <a href="/en/good-finds/riviera-mistakes/">7 ways to get the Riviera wrong</a>.</p></div><div class="verdict-box"><span>When the heat is brutal</span><p>Move climbs, exposed old towns and longer walks to the morning. Use the hottest hours for museums, lunch, shade or a swim, then resume later. On those days, Èze at midday is not a character-building exercise worth scheduling.</p></div><h2 id="book-ahead">',1)
    new='<h2 id="book-ahead">Book ahead: the short checklist</h2><p>Reserve the things whose absence would genuinely damage the trip; leave the rest able to move with weather and energy.</p><div class="verdict-box"><span>4–8 weeks before</span><p><strong>Hotel:</strong> book the base you actually want. <strong>Signature dinners:</strong> reserve one or two small or destination restaurants if missing them would annoy you. <strong>Defining experiences:</strong> secure any timed museum, boat or guided activity that is the reason for a day.</p></div><div class="verdict-box"><span>1–2 weeks before</span><p>Recheck opening days and book seasonal boats or popular timed activities. Do not pre-book every lunch simply because an empty slot makes you nervous.</p></div><div class="verdict-box"><span>24–48 hours before</span><p>Check official rail/bus planners, weather and disruption. Ordinary coastal train journeys belong to the flexible layer: verify current fares and conditions rather than treating an old blog post as a ticket office.</p></div><div class="verdict-box"><span>Keep spontaneous</span><p>Most lunches, one half-day, the exact order of weather-sensitive days and the decision to stop for a swim instead of collecting another landmark.</p></div><h2 id="make-it-three">'
    s,n=re.subn(r'<h2 id="book-ahead">.*?<h2 id="make-it-three">',new,s,1,flags=re.S)
    if n!=1:raise RuntimeError('EN book-ahead block not found')
    wr(p,s)
    p='fr/planifier/cinq-jours-nice-sans-voiture/index.html';s=nav(rd(p),'fr')
    if '/riviera-guide/eze/' not in s:s=s.replace('<p><strong>Règle Mametas :</strong> la journée flexible n’est pas un échec de planification. C’est ce qui permet au reste de ressembler à des vacances.</p></div>','<p><strong>Règle Mametas :</strong> la journée flexible n’est pas un échec de planification. C’est ce qui permet au reste de ressembler à des vacances.</p><p><a class="inline-decision-link" href="/riviera-guide/eze/">Si vous choisissez Èze, utilisez le guide du village plutôt que d’improviser la montée →</a></p></div>',1)
    if 'Une mauvaise météo n’annule pas le séjour' not in s:s=s.replace('<h2 id="reservations">','<div class="verdict-box"><span>Une mauvaise météo n’annule pas le séjour</span><p>Si Nice se réveille grise, changez de programme : <a href="/bons-plans/nice-quand-il-pleut/">utilisez notre plan Nice sous la pluie</a>. Avant d’ajouter une excursion, lisez <a href="/bons-plans/erreurs-riviera/">7 façons de rater la Riviera</a>.</p></div><div class="verdict-box"><span>Quand il fait très chaud</span><p>Placez montées, vieilles villes exposées et longues marches le matin. Gardez le cœur de journée pour musée, déjeuner, ombre ou baignade, puis repartez plus tard. Ces jours-là, Èze à midi n’est pas une épreuve de caractère à programmer.</p></div><h2 id="reservations">',1)
    m=re.search(r'<h2 id="reservations">.*?<h2 id="([^\"]+)">',s,re.S)
    if not m:raise RuntimeError('FR reservation block not found')
    nxt=m.group(1);new='<h2 id="reservations">Réserver à l’avance : la check-list courte</h2><p>Bloquez ce dont l’absence gâcherait vraiment le séjour ; laissez le reste bouger avec la météo et l’énergie.</p><div class="verdict-box"><span>4 à 8 semaines avant</span><p><strong>Hôtel :</strong> réservez la base que vous voulez réellement. <strong>Dîners signature :</strong> bloquez une ou deux petites tables ou tables-destination que vous regretteriez de manquer. <strong>Expériences qui définissent une journée :</strong> réservez musée à créneau, bateau ou activité guidée si c’est la raison principale du déplacement.</p></div><div class="verdict-box"><span>1 à 2 semaines avant</span><p>Revérifiez les jours d’ouverture et réservez les bateaux saisonniers ou activités à créneau populaires. Ne réservez pas chaque déjeuner uniquement parce qu’une case vide vous inquiète.</p></div><div class="verdict-box"><span>24 à 48 h avant</span><p>Vérifiez les calculateurs officiels train/bus, la météo et les perturbations. Les trajets côtiers ordinaires restent la couche flexible : contrôlez les tarifs et conditions du moment plutôt que de transformer un vieux billet de blog en guichet SNCF.</p></div><div class="verdict-box"><span>À garder spontané</span><p>La plupart des déjeuners, une demi-journée, l’ordre exact des journées sensibles à la météo et le droit de choisir une baignade plutôt qu’un monument supplémentaire.</p></div><h2 id="'+nxt+'">'
    s=s[:m.start()]+new+s[m.end():];wr(p,s)

