    for p in TOUCHED:
        if (ROOT/p).is_file():wr(p,nav(rd(p),'en' if p.startswith('en/') or p.startswith('plan/') else 'fr'))
    print('Claude audit 2026-09-13 corrections applied.')
    return 0
